class Security{constructor(){this.rateLimits=new Map,this.loginAttempts=0,this.lockoutUntil=0}sanitizeInput(t){return"string"!=typeof t?"":t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#x27;").replace(/\//g,"&#x2F;")}sanitizeForDisplay(t){const e=document.createElement("div");return e.textContent=t,e.innerHTML}isValidEmail(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}isValidName(t){return/^[a-zA-Z\s'-]{1,100}$/.test(t)}validateGuestbookEntry(t){const e=[];return!t.name||t.name.trim().length<1?e.push("Name is required"):t.name.length>100&&e.push("Name must be under 100 characters"),!t.message||t.message.trim().length<1?e.push("Message is required"):t.message.length>280&&e.push("Message must be under 280 characters"),t.email&&!this.isValidEmail(t.email)&&e.push("Invalid email format"),{valid:0===e.length,errors:e,sanitized:{name:this.sanitizeInput(t.name||"").trim(),message:this.sanitizeInput(t.message||"").trim(),email:t.email?this.sanitizeInput(t.email).trim():""}}}isRateLimited(t,e=5,i=6e4){const s=Date.now(),a=t;this.rateLimits.has(a)||this.rateLimits.set(a,{attempts:[],blockedUntil:0});const n=this.rateLimits.get(a);if(n.blockedUntil>s){return{limited:!0,remainingSeconds:Math.ceil((n.blockedUntil-s)/1e3)}}return n.attempts=n.attempts.filter(t=>s-t<i),n.attempts.length>=e?(n.blockedUntil=s+i,{limited:!0,remainingSeconds:Math.ceil(i/1e3)}):(n.attempts.push(s),{limited:!1})}resetRateLimit(t){this.rateLimits.delete(t)}checkLoginAttempt(){const t=Date.now();if(this.lockoutUntil>t){return{allowed:!1,remainingSeconds:Math.ceil((this.lockoutUntil-t)/1e3)}}return{allowed:!0}}recordFailedLogin(){return this.loginAttempts++,this.loginAttempts>=5?(this.lockoutUntil=Date.now()+3e5,this.loginAttempts=0,{locked:!0,lockoutMinutes:5}):{locked:!1,attemptsRemaining:5-this.loginAttempts}}resetLoginAttempts(){this.loginAttempts=0,this.lockoutUntil=0}createSession(t,e=24){const i={authenticated:!0,created:Date.now(),expires:Date.now()+60*e*60*1e3};localStorage.setItem(t,JSON.stringify(i))}isSessionValid(t){try{const e=JSON.parse(localStorage.getItem(t));return!!e&&(Date.now()>e.expires?(localStorage.removeItem(t),!1):!0===e.authenticated)}catch{return!1}}clearSession(t){localStorage.removeItem(t)}}export const security=new Security;